import{_ as t,a,o as s,a4 as o}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Checkout","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/checkout/index.md","filePath":"api/rest-api/shop/checkout/index.md","lastUpdated":1783420618000}'),d={name:"api/rest-api/shop/checkout/index.md"};function h(r,e,i,p,n,c){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h1><p>The Checkout menu turns a prepared cart into a placed order. It runs as a sequence: set the addresses, choose a shipping method, choose a payment method, then place the order.</p><h2 id="the-checkout-sequence" tabindex="-1">The checkout sequence <a class="header-anchor" href="#the-checkout-sequence" aria-label="Permalink to &quot;The checkout sequence&quot;">​</a></h2><p>Checkout is order-sensitive — each step unlocks the next:</p><ol><li><strong>Set the shipping and billing addresses</strong> (or read back the saved ones). Addresses are required before shipping rates can be calculated.</li><li><strong>Get shipping methods</strong> for the cart, then <strong>set</strong> the chosen one.</li><li><strong>Get payment methods</strong>, then <strong>set</strong> the chosen one.</li><li><strong>Place the order</strong> to finalise the cart into an order.</li></ol><p>Calling a step out of order (e.g. asking for shipping methods before addresses are saved) is rejected — complete the earlier step first.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/checkout/get-addresses.html">Get Addresses</a></td><td><code>GET /api/shop/checkout-addresses</code></td><td>Read the addresses saved on the cart.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a></td><td><code>POST /api/shop/checkout-addresses</code></td><td>Save the shipping address.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a></td><td><code>POST /api/shop/checkout-addresses</code></td><td>Save the billing address.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">Get Shipping Methods</a></td><td><code>GET /api/shop/checkout-shipping-methods</code></td><td>List available shipping rates.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a></td><td><code>POST /api/shop/checkout-shipping-methods</code></td><td>Select a shipping method.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a></td><td><code>GET /api/shop/checkout-payment-methods</code></td><td>List available payment methods.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a></td><td><code>POST /api/shop/checkout-payment-methods</code></td><td>Select a payment method.</td></tr><tr><td><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a></td><td><code>POST /api/shop/checkout-orders</code></td><td>Finalise the cart into an order.</td></tr></tbody></table><p>All Checkout endpoints require the storefront key and the active cart&#39;s token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',9)]))}const m=t(d,[["render",h]]);export{u as __pageData,m as default};
